param([ValidateSet('client32','host32','host64')][string]$CompileRole)
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$source = Join-Path $root '.deps/dxvk-remix'
$out = Join-Path $root 'work/ipc-full-native'
if ($CompileRole) {
  $arch = if ($CompileRole -eq 'host64') { 'x64' } else { 'x86' }
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $arch -VcVarsVer '14.29'
  Push-Location $out
  try {
    [string[]]$flags = if ($CompileRole -eq 'host32') { @('/DREMIX_BRIDGE_X86_SERVER','/DREMIX_BRIDGE_SERVER') } else { @() }
    if (Test-Path "$out/mapped_buffer_template.h") { $flags += '/DLDB_MAPPED_BUFFER_TRANSPORT' }
    & cl.exe /nologo /std:c++17 /EHsc /O2 /DNDEBUG /W3 /DNOMINMAX /DWIN32 @flags "/I$out" ipc_transport.cpp util_sharedmemory.cpp util_semaphore.cpp data_diagnostics.cpp exception_diagnostics.cpp "/Fe:transport-$CompileRole.exe" /link /LARGEADDRESSAWARE ole32.lib psapi.lib
    if ($LASTEXITCODE -ne 0) { throw "Full transport compile: $CompileRole" }
    & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /wd4324 /DNOMINMAX "/I$out" "$root/tests/ipc-v2/full.cpp" "/Fe:full-$arch.exe"
    if ($LASTEXITCODE -ne 0) { throw 'Full policy compile' }
    & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /wd4324 /DNOMINMAX "/I$out/ipc_v2" "$root/tests/ipc-v2/native.cpp" "/Fe:core-$arch.exe"
    if ($LASTEXITCODE -ne 0) { throw 'Existing v2 core regression compile' }
  } finally { Pop-Location }
} else {
  python "$PSScriptRoot/generate_ipc_full_test.py"
  if ($LASTEXITCODE -ne 0) { throw 'Extraction failed' }
  foreach ($role in @('client32','host32','host64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileRole $role
    if ($LASTEXITCODE -ne 0) { throw "Full build failed $role" }
  }
  python "$PSScriptRoot/run_ipc_full_tests.py"
  if ($LASTEXITCODE -ne 0) { throw 'Full native tests failed' }
}
